#!/usr/bin/perl
use strict; use warnings;
my $BIN="/workspace/dataset/test15_executable";
# run(args...) -> (rc, stdout, stderr)
sub run6 {
  my @a=@_;
  die "need 6" unless @a==6;
  my $tmpo="/tmp/_o.$$"; my $tmpe="/tmp/_e.$$";
  my $pid=fork(); 
  if($pid==0){ open(STDOUT,'>',$tmpo); open(STDERR,'>',$tmpe); exec($BIN,@a); exit 127; }
  waitpid($pid,0); my $rc=$?; my $code = ($rc & 127) ? 128+($rc&127) : ($rc>>8);
  local $/; open(my $fo,'<',$tmpo); binmode $fo; my $o=<$fo>//''; close $fo;
  open(my $fe,'<',$tmpe); binmode $fe; my $e=<$fe>//''; close $fe;
  unlink $tmpo,$tmpe;
  return ($code,$o,$e);
}
sub h { return unpack("H*", $_[0]); }
sub esc { my $s=shift; $s =~ s/([^\x20-\x7e])/sprintf("<%02x>",ord($1))/ge; return $s; }
sub show {
  my ($tag,@a)=@_;
  my ($rc,$o,$e)=run6(@a);
  print "== $tag\n";
  print "   args: ", join(" | ", map { "[".esc($_)."]" } @a), "\n";
  print "   rc=$rc  stdout_hex_len=".length($o)."\n";
  my @L=split(/\n/,$o,-1); pop @L if @L && $L[-1] eq '';
  for my $i (0..$#L){ printf("   %d: [%s] hex=%s\n", $i+1, esc($L[$i]), h($L[$i])); }
  print "   NLINES=".scalar(@L)."\n";
  print "   STDERR: ".esc(substr($e,0,300))."\n" if length $e;
  return ($rc,$o,$e);
}
1;
